// HOOK-A v2 (hook-1 .. hook-3), Rokossovsky #8. Basemap bobruisk_hd_ref (Belarus z9, HD relief, dark Frontlines grade).
// Owner 2026-10-07: v1 too slow -> something new every 2-4 s, SFX on every beat, beats timed to the words (B.at).
// hook-1: wide Belarus (option 1), long red line vs blue line, units moving at frame 0; BIG card slams in at 0.3 s and ticks to
//         ~400,000 GERMAN LOSSES (small: whole operation); red counters crack and grey in waves; ONE SUMMER stamp;
//         on "a swamp": hard zoom-whoosh DIVE into the Pripyat marsh (switch to option 2 glowing lines), IMPASSABLE stamp.
// hook-2: log roads draw across the bog, a mystery "?" badge (one Soviet general), tanks + cavalry burst out of the marsh, ALERT + MG
//         + impacts; WHITE-FLASH cut -> 27 JUNE: two arrows race round Bobruisk, the ring slams shut, TRAPPED; zoom-out whoosh:
//         option 1 (4 July), arrows sweep west, ARMY GROUP CENTRE (once at the gates of Moscow) torn apart, struck through.
// hook-3: hard cut to dark, 1944 rolls back to 1937, photo badge, prison bars SLAM down, NKVD card, stamps on each spoken beat
//         (ARRESTED / TEETH / RIBS / MOCK EXECUTION x2, family-account caption), NEVER SIGNED A FALSE CONFESSION, bars lift.
// v1 kept in scenes-src/old/hook-a_v1.js. Facts: research/FACT_NOTES.md + FACT_NOTES_bobruisk.md (fronts per date).
const B = Battle();
const { at, P: PS } = B;
const END = B.T.duration;
const K = FXK(B);
const GG = GGK(B);
const PR = GG.proj(9, 74836, 41886);
const L = (lat, lon) => PR(lat, lon);
const USSR = "assets/media/ussr_flag.png", REICH = "assets/media/ger_reich_flag.png";
const PHOTO_ROKO = "assets/media/rokossovsky_head.png"; // licensed head shot (credits: assets/media/CREDITS.md)
const tl = B.tl, scene = document.getElementById("scene"), worldEl = document.getElementById("world");
// ---------- helpers ----------
const box = (txt, x, y, t, size = 16, until, pop = true) => { if (pop) SFX("ref:pop", t); return GG.pin(`<div style="background:#f1eee6;color:#111;font-family:Oswald;font-weight:500;letter-spacing:.28em;padding:${Math.round(size * 0.2)}px ${Math.round(size * 0.35)}px ${Math.round(size * 0.2)}px ${Math.round(size * 0.6)}px;font-size:${size}px;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.6)">${txt}</div>`, x, y, { t, until }); };
const town = (txt, lat, lon, t, o = {}) => { const [x, y] = L(lat, lon); B.city("", x, y, { r: o.r || 5, t }); return box(txt, x + (o.dx || 0), y + (o.dy != null ? o.dy : -22), t, o.size || 13, o.until, false); };
const flag = (src, name, x, y, t, until, w = 76) => { const el = GG.pin(`<div style="display:flex;flex-direction:column;align-items:center;gap:${Math.round(w * 0.05)}px"><img src="${src}" style="width:${w}px;display:block;border:${Math.max(1, Math.round(w / 40))}px solid #1a1712;box-shadow:0 3px 8px rgba(0,0,0,0.55)"><div class="gg-lbl" style="position:relative;font-size:${Math.round(w * 0.24)}px;color:#f7f3ea;text-shadow:0 2px 4px #000;letter-spacing:0.08em">${name}</div></div>`, x, y, { t: t === 0 ? null : t, pop: true, until }); if (t === 0) gsap.set(el, { autoAlpha: 1 }); return el; };
const unitXY = (id, side, x, y, icon, label, o = {}) => {
  const w = o.w || 34, h = o.h || 23;
  B.unit({ id, side, x, y, w, h, t: o.t, label });
  K.counter(id, { icon, flag: "ger" });
  if (side === "carth") B.units[id].el.querySelector(".fxk-flag").src = USSR;   // lib/fx.js FLAGS has no USSR key: set the chip here
  const tg = B.units[id].el.querySelector(".tag"); if (tg && o.tag) tg.style.fontSize = o.tag + "px";
  if (o.t == null) gsap.set(B.units[id].el, { autoAlpha: 1 });                   // on screen from frame 0
  return id;
};
const unit = (id, side, lat, lon, icon, label, o = {}) => unitXY(id, side, ...L(lat, lon), icon, label, o);
const go = (id, t, dur, lat, lon, ease) => { const [x, y] = L(lat, lon); B.move(id, t, dur, x, y, ease || "power1.inOut"); };
const goXY = (id, t, dur, x, y, ease) => B.move(id, t, dur, x, y, ease || "power1.inOut");
const ringPts = (pts) => pts.map(([la, lo]) => L(la, lo));
// screen-space element (above the map, under the credit)
const scr = (html, css) => { const el = document.createElement("div"); el.style.cssText = "position:absolute;" + css; el.innerHTML = html; scene.insertBefore(el, document.getElementById("credit")); GG.hide(el); return el; };
// SLAM: punch in from big (stamp feel) + hit + small shake
const slam = (el, t, o = {}) => {
  tl.fromTo(el, { autoAlpha: 0, scale: o.from || 2.2 }, { autoAlpha: 1, scale: 1, duration: o.dur || 0.24, ease: "power4.in" }, t);
  const tHit = t + (o.dur || 0.24) - 0.02;
  if (o.sfx !== false) SFX(o.sfx || "hit", tHit);
  if (o.shake !== false) K.shake(tHit, o.shake || 4, 0.3);
  if (o.until != null) tl.to(el, { autoAlpha: 0, duration: 0.35 }, o.until);
  return el;
};
const stampHTML = (txt, c, size, rot, sub) => `<div style="transform:rotate(${rot}deg);display:inline-block;text-align:center;font-family:Oswald;font-weight:700;color:${c};border:${Math.max(4, Math.round(size / 9))}px solid ${c};padding:4px 22px 6px;background:rgba(14,12,10,0.72);box-shadow:0 10px 26px rgba(0,0,0,.55);white-space:nowrap"><div style="font-size:${size}px;letter-spacing:0.12em;line-height:1.1">${txt}</div>${sub ? `<div style="font-size:${Math.round(size * 0.36)}px;letter-spacing:0.22em;color:#d8cfb8">${sub}</div>` : ""}</div>`;
// world-space stamp slammed onto the map
const wstamp = (txt, x, y, t, o = {}) => slam(GG.pin(stampHTML(txt, o.color || "#e3232f", o.size || 40, o.rot || -6), x, y), t, o);
const logRoad = (pts, t, dur = 1.6, until) => {   // corduroy log road: brown ties on a dark bed, revealed along the path
  const NS = "http://www.w3.org/2000/svg", svg = document.getElementById("overlay"), g = document.createElementNS(NS, "g");
  const d = "M" + pts.map((q) => q[0].toFixed(1) + " " + q[1].toFixed(1)).join(" L");
  const id = "lr" + Math.round(pts[0][0] * 7 + pts[0][1]);
  g.innerHTML = `<mask id="${id}" maskUnits="userSpaceOnUse" x="0" y="0" width="2880" height="1620"><path d="${d}" fill="none" stroke="#fff" stroke-width="16" stroke-linecap="round"/></mask>
    <g mask="url(#${id})"><path d="${d}" fill="none" stroke="rgba(30,20,10,0.75)" stroke-width="10" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#c49a5e" stroke-width="7" stroke-dasharray="2 3"/></g>`;
  svg.appendChild(g);
  const mp = g.querySelector("mask path"), len = mp.getTotalLength();
  gsap.set(mp, { strokeDasharray: `${len} ${len}`, strokeDashoffset: len });
  tl.to(mp, { strokeDashoffset: 0, duration: dur, ease: "power1.inOut" }, t);
  if (until != null) tl.to(g, { opacity: 0, duration: 0.4 }, until);
  return g;
};
const legend = (t, until, opt2) => { const html = `<div style="display:flex;gap:26px;font-size:20px;letter-spacing:0.1em;align-items:center">${[["#2e5cb2", "#2c57b7", "SOVIET"], ["#be3a2a", "#bc2528", "GERMAN"]].map(([sq, ln, nm]) => `<span><b style="display:inline-block;width:20px;height:${opt2 ? 6 : 20}px;background:${opt2 ? ln : sq};${opt2 ? `box-shadow:0 0 8px ${ln};vertical-align:4px;` : "vertical-align:-3px;"}margin-right:8px;border:1px solid #f7f3ea"></b>${nm}</span>`).join("")}</div>`;
  if (t > 0) return GG.card(html, "", 34, t, until);
  const el = document.createElement("div"); el.className = "gg-card"; el.style.top = "34px"; el.innerHTML = `<div class="inner">${html}</div>`;   // up at frame 0
  scene.insertBefore(el, document.getElementById("credit")); if (until != null) GG.fadeOut(el, until, 0.6); return el; };
const ctl = (state, t, dur, until) => { const el = B.image(`assets/media/bobruisk_ctl_${state}_mx.png`, 0, 0, 2880, 1620, { t, dur, until }); el.style.mixBlendMode = "multiply"; return el; };
const img0 = (src, until, mx) => {   // world image visible from frame 0 (no reveal tween), optional fade-out
  const el = document.createElement("img"); el.className = "wimg"; el.src = src; el.alt = "";
  Object.assign(el.style, { left: "0px", top: "0px", width: "2880px", height: "1620px" }); if (mx) el.style.mixBlendMode = "multiply";
  worldEl.insertBefore(el, document.getElementById("overlay"));
  if (until != null) tl.to(el, { autoAlpha: 0, duration: 0.6 }, until);
  return el;
};
const date0 = (text, until) => {     // date scroll already showing at frame 0
  const d = document.createElement("div"); d.className = "d"; d.textContent = text; d.style.fontSize = "32px";
  document.getElementById("date").appendChild(d);
  if (until != null) tl.to(d, { autoAlpha: 0, y: -14, duration: 0.3 }, until);
};
// camera with per-move eases (B.camera only does sine.inOut): hard dives, instant cuts
const CW = 1920, CH = 1080, cam = { cx: 1450, cy: 800, s: 0.8 };
const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);
const applyCam = () => { const s = Math.max(cam.s, CW / 2880), cx = clamp(cam.cx, CW / 2 / s, 2880 - CW / 2 / s), cy = clamp(cam.cy, CH / 2 / s, 1620 - CH / 2 / s); gsap.set(worldEl, { x: CW / 2 - cx * s, y: CH / 2 - cy * s, scale: s }); };
applyCam();
const camTo = (t, dur, cx, cy, s, ease = "sine.inOut") => tl.to(cam, { cx, cy, s, duration: Math.max(dur, 0.01), ease, onUpdate: applyCam }, t);
// along a polyline: point at fraction f + unit normal pointing to the Soviet side (same side K.front puts the blue glow)
const along = (pts, f) => {
  const seg = []; let tot = 0; for (let j = 1; j < pts.length; j++) { const d = Math.hypot(pts[j][0] - pts[j - 1][0], pts[j][1] - pts[j - 1][1]); seg.push(d); tot += d; }
  let d = f * tot; for (let j = 0; j < seg.length; j++) { if (d <= seg[j] || j === seg.length - 1) { const k = Math.min(1, d / seg[j]), a = pts[j], b = pts[j + 1];
    const dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1; return [a[0] + dx * k, a[1] + dy * k, dy / l, -dx / l]; } d -= seg[j]; }
};
